@namespace sv_49c2dbc8f10f47838d1f159a7163a1bd.Components.Pages.Apply

<div class="review-step">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <h3>&#10003; Application Submitted Successfully!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you soon.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@FullName</dd>
                <dt>Email</dt><dd>@Email</dd>
                <dt>Phone</dt><dd>@Phone</dd>
                <dt>Address</dt><dd>@Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="date-range">
                        @entry.StartDate.ToString("MMM yyyy") &ndash;
                        @(entry.IsCurrentPosition ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="validation-summary">@ErrorMessage</div>
        }

        <div class="step-actions">
            <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public List<WorkEntryForm.WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferenceForm.ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback OnSubmit { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int? ApplicationId { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }

    private async Task HandleSubmit()
    {
        await OnSubmit.InvokeAsync();
    }
}

arguments.file_text:
@page "/apply"
@namespace sv_49c2dbc8f10f47838d1f159a7163a1bd.Components.Pages.Apply
@using sv_49c2dbc8f10f47838d1f159a7163a1bd.Models
@using sv_49c2dbc8f10f47838d1f159a7163a1bd.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-wizard">
    <StepIndicator CurrentStep="@currentStep" CompletedSteps="@completedSteps" OnNavigate="NavigateToStep" />

    <div class="step-content">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalInfoNext" />
                break;

            case 1:
                <WorkHistoryStep Entries="@workEntries" OnNext="HandleWorkHistoryNext" OnBack="GoBack" />
                break;

            case 2:
                <ReferencesStep References="@references" OnNext="HandleReferencesNext" OnBack="GoBack" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="@coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
                break;

            case 4:
                <ReviewStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                            WorkEntries="@workEntries" References="@references" CoverLetter="@coverLetter"
                            OnSubmit="HandleSubmit" OnBack="GoBack" OnEditStep="NavigateToStep"
                            IsSubmitting="@isSubmitting" IsSubmitted="@isSubmitted"
                            ApplicationId="@applicationId" ErrorMessage="@submitError" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep = 0;
    private HashSet<int> completedSteps = new();

    // Step 1 state
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> workEntries = new() { new() };

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> references = new() { new(), new() };

    // Step 4 state
    private string coverLetter = "";

    // Submission state
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;
    private string? submitError;

    private void HandlePersonalInfoNext((string FullName, string Email, string Phone, string Address) data)
    {
        fullName = data.FullName;
        email = data.Email;
        phone = data.Phone;
        address = data.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var workHistory = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList());

            var refList = references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(
                new PersonalInfo(fullName, email, phone, address),
                workHistory,
                refList,
                coverLetter);

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
            completedSteps.Add(4);
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private void GoBack()
    {
        if (currentStep > 0)
        {
            currentStep--;
        }
    }

    private void NavigateToStep(int step)
    {
        if (completedSteps.Contains(step))
        {
            currentStep = step;
        }
    }
}

.application-wizard {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
