toolArgs.file_text:
.application-wizard {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    align-items: center;
    list-style: none;
    padding: 0;
    margin: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    flex: 0 0 auto;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.875rem;
    border: 2px solid #d1d5db;
    background: #fff;
    color: #6b7280;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    border-color: #2563eb;
    background: #2563eb;
    color: #fff;
}

.step-item.completed .step-circle {
    border-color: #16a34a;
    background: #16a34a;
    color: #fff;
}

.step-item.dimmed .step-circle {
    opacity: 0.5;
}

.checkmark {
    font-size: 1rem;
}

.step-label {
    margin-top: 0.5rem;
    font-size: 0.75rem;
    text-align: center;
    color: #6b7280;
    white-space: nowrap;
}

.step-item.active .step-label {
    color: #2563eb;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #16a34a;
}

.step-item.dimmed .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #d1d5db;
    margin: 0 0.5rem;
    margin-bottom: 1.5rem;
}

.step-connector.completed {
    background: #16a34a;
}

.step-connector.active {
    background: #2563eb;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 2rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    color: #374151;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.9rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: 400 !important;
    margin-top: 0.5rem;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.btn {
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    border: none;
    transition: all 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #2563eb;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background: #1d4ed8;
}

.btn-outline {
    background: #fff;
    color: #374151;
    border: 1px solid #d1d5db;
}

.btn-outline:hover {
    background: #f9fafb;
}

.btn-secondary {
    background: #f3f4f6;
    color: #374151;
    border: 1px solid #d1d5db;
}

.btn-secondary:hover {
    background: #e5e7eb;
}

.btn-danger {
    background: #fee2e2;
    color: #dc2626;
    border: 1px solid #fecaca;
}

.btn-danger:hover {
    background: #fecaca;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

.btn-link {
    background: none;
    border: none;
    color: #2563eb;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #1d4ed8;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

/* Step Actions */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e5e7eb;
}

/* Validation */
.validation-summary {
    background: #fef2f2;
    border: 1px solid #fecaca;
    color: #dc2626;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-top: 1rem;
    font-size: 0.875rem;
}

.field-error {
    color: #dc2626;
    font-size: 0.8rem;
    margin-top: 0.25rem;
    display: block;
}

/* Work Entry & Reference Forms */
.work-entry-form,
.reference-form {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1rem;
}

.work-entry-form legend,
.reference-form legend {
    font-weight: 600;
    color: #374151;
    padding: 0 0.5rem;
}

/* Cover Letter */
.cover-letter-textarea {
    resize: vertical;
    min-height: 200px;
}

.character-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

/* Review Step */
.review-section {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #1f2937;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #6b7280;
}

.review-section dd {
    margin: 0;
    color: #1f2937;
}

.review-work-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f3f4f6;
}

.review-work-entry:last-child {
    border-bottom: none;
}

.date-range {
    font-size: 0.85rem;
    color: #6b7280;
}

.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f3f4f6;
}

.review-reference:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f9fafb;
    padding: 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
    max-height: 200px;
    overflow-y: auto;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 2rem;
}

.submission-confirmation h3 {
    color: #16a34a;
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.submission-confirmation p {
    color: #374151;
    font-size: 1rem;
}

/* Step Description */
.step-description {
    color: #6b7280;
    margin-bottom: 1.5rem;
}

