@namespace sv_49c2dbc8f10f47838d1f159a7163a1bd.Components.Pages.Apply

<fieldset class="work-entry-form">
    <legend>Position @(Index + 1)</legend>

    <div class="form-group">
        <label>Company *</label>
        <input type="text" value="@Entry.Company" @onchange="OnCompanyChanged" class="form-control" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="OnTitleChanged" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChanged" class="form-control" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd"))" @onchange="OnEndDateChanged" class="form-control" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="ToggleCurrent" /> Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="OnDescriptionChanged" class="form-control" rows="3"></textarea>
    </div>

    @if (CanRemove)
    {
        <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrentPosition;

    private Task OnCompanyChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { Company = e.Value?.ToString() ?? "" });

    private Task OnTitleChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { Title = e.Value?.ToString() ?? "" });

    private Task OnStartDateChanged(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        if (DateTime.TryParse(val, out var date))
            return OnChanged.InvokeAsync(Entry with { StartDate = date });
        return Task.CompletedTask;
    }

    private Task OnEndDateChanged(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        var endDate = string.IsNullOrEmpty(val) ? (DateTime?)null : DateTime.Parse(val);
        return OnChanged.InvokeAsync(Entry with { EndDate = endDate });
    }

    private Task OnDescriptionChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { Description = e.Value?.ToString() ?? "" });

    private Task ToggleCurrent(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        return OnChanged.InvokeAsync(Entry with { IsCurrentPosition = isCurrent, EndDate = isCurrent ? null : Entry.EndDate });
    }

    public record WorkEntryModel
    {
        public string Company { get; init; } = "";
        public string Title { get; init; } = "";
        public DateTime StartDate { get; init; } = DateTime.Today;
        public DateTime? EndDate { get; init; }
        public string Description { get; init; } = "";
        public bool IsCurrentPosition { get; init; }
    }
}

